import { useEffect,useState,useCallback } from 'react'; import { useMutation,useQuery,useQueryClient } from '@tanstack/react-query'; import { useNavigate } from 'react-router-dom'; import { authApi } from '../api/auth'; import { useAuthStore } from '../store/authStore'; import type { HospitalLoginRequest } from '../types/models'
export function useHospitalMe(enabled=true){return useQuery({queryKey:['hospital-me'],queryFn:authApi.me,enabled,retry:false})}
export function useHospitalLogin(){const nav=useNavigate(); const qc=useQueryClient(); const set=useAuthStore(s=>s.setSession); return useMutation({mutationFn:(p:HospitalLoginRequest)=>authApi.login(p),onSuccess:d=>{set({token:d.token,user:d.user,hospital:d.hospital,staff:d.staff});void qc.invalidateQueries();nav('/dashboard',{replace:true})}})}
export function useHospitalSession(){const token=useAuthStore(s=>s.token),user=useAuthStore(s=>s.user),restoreSession=useAuthStore(s=>s.restoreSession),clear=useAuthStore(s=>s.clearSession); const [isRestoring,setR]=useState(Boolean(token&&!user)); const restore=useCallback(async()=>{if(!token||user){setR(false);return} try{const s=await authApi.me();restoreSession(s)}catch{clear()}finally{setR(false)}},[token,user,restoreSession,clear]); useEffect(()=>{void restore()},[restore]); return{isRestoring}}
